			gsap.to("#hand", {
				duration: 0.6,
				rotation: 15,
				// IMPORTANT: Use absolute viewBox coordinates for SVG pivots!
				// 530 860 is the approximate location of the wrist joint.
				svgOrigin: "530 860",
				ease: "power1.inOut",
				repeat: -1,
				yoyo: true,
			});

			// 2. Subtle Breathing Animation for the body
			// gsap.to("#body", {
			// 	duration: 2.5,
			// 	scaleY: 1.015,
